package com.luminor.tavernquest.di
import com.luminor.tavernquest.data.local.database.*;import com.luminor.tavernquest.data.local.database.dao.*;import com.luminor.tavernquest.data.local.preferences.SettingsDataSource;import com.luminor.tavernquest.data.repository.*;import com.luminor.tavernquest.domain.repository.*;import dagger.Module;import dagger.Provides;import dagger.hilt.InstallIn;import dagger.hilt.components.SingletonComponent;import javax.inject.Singleton
@Module @InstallIn(SingletonComponent::class) object RepositoryModule{@Provides @Singleton fun heroRepo(d:HeroDao):HeroRepository=HeroRepositoryImpl(d);@Provides @Singleton fun tavernRepo(db:TavernQuestDatabase):TavernRepository=TavernRepositoryImpl(db);@Provides @Singleton fun feedRepo(d:TavernFeedDao):TavernFeedRepository=TavernFeedRepositoryImpl(d);@Provides @Singleton fun contractRepo(db:TavernQuestDatabase):ContractRepository=ContractRepositoryImpl(db);@Provides @Singleton fun questRepo(db:TavernQuestDatabase,ids:com.luminor.tavernquest.core.util.UuidProvider):QuestRepository=QuestRepositoryImpl(db,ids);@Provides @Singleton fun journalRepo(d:QuestCompletionDao):JournalRepository=JournalRepositoryImpl(d);@Provides @Singleton fun xpRepo(d:XpLedgerDao):XpRepository=XpRepositoryImpl(d);@Provides @Singleton fun dashboardRepo(d:ActivityDao):DashboardRepository=DashboardRepositoryImpl(d);@Provides @Singleton fun rankingRepo(d:ActivityDao):RankingRepository=RankingRepositoryImpl(d);@Provides @Singleton fun syncRepo(db:TavernQuestDatabase):SyncRepository=SyncRepositoryImpl(db);@Provides @Singleton fun settingsRepo(d:SettingsDataSource):SettingsRepository=SettingsRepositoryImpl(d)}
